import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.CjNDb28q.js";var i=JSON.parse(`{"title":"Guides","description":"","frontmatter":{},"headers":[],"relativePath":"guides/index.md","filePath":"guides/index.md"}`),a={name:`guides/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to “Guides”">​</a></h1><p>manko content and tracker extensions connect the app to external services. The repository does not host comics. Theme extensions are not supported.</p><h2 id="browse-extensions" tabindex="-1">Browse extensions <a class="header-anchor" href="#browse-extensions" aria-label="Permalink to “Browse extensions”">​</a></h2><p>The <a href="/extensions/extension-list">Extension List</a> shows the extension&#39;s icon, name, current version, content rating, and provider website. Sources are grouped by language, with Multi-Language first. Content and tracker extensions appear in the same list.</p><div class="tip custom-block"><p class="custom-block-title">Keep extensions current</p><p>Refresh a repository to check for newer manifest versions, then use Update for the extensions you want to replace.</p></div><h2 id="custom-catalogs" tabindex="-1">Custom catalogs <a class="header-anchor" href="#custom-catalogs" aria-label="Permalink to “Custom catalogs”">​</a></h2><p>To use another publisher&#39;s repository, add its HTTPS repository URL inside Manko. A compatible repository contains <code>versioning.json</code> and versioned API 2.0 WASM modules. The website displays this repository&#39;s catalog; manage other repositories in the app.</p><h2 id="install-an-extension" tabindex="-1">Install an extension <a class="header-anchor" href="#install-an-extension" aria-label="Permalink to “Install an extension”">​</a></h2><p>Search by name, ID, or provider website, or filter by <strong>Language</strong> and <strong>Content Rating</strong>. The total count updates as you filter, and language groups with no matching sources disappear.</p><p>Choose the arrow on a source row to open that extension&#39;s catalog entry in Manko, then select Get or Update. Retired and unavailable entries have disabled arrows. <strong>Add Repository</strong> opens the repository catalog without selecting an extension; it never installs code automatically.</p><h2 id="content-ratings" tabindex="-1">Content ratings <a class="header-anchor" href="#content-ratings" aria-label="Permalink to “Content ratings”">​</a></h2><table tabindex="0"><thead><tr><th>Rating</th><th>Intended use</th></tr></thead><tbody><tr><td>Safe</td><td>General-audience material.</td></tr><tr><td>Contains NSFW (17+)</td><td>The publisher marks this source as Mature.</td></tr><tr><td>NSFW (18+)</td><td>The publisher marks this source as Adult.</td></tr><tr><td>Unknown</td><td>The publisher did not provide a recognized rating.</td></tr></tbody></table><p>The Extension List shows every rating by default. Choose a rating from the <strong>Content Rating</strong> menu to filter the catalog; choose <strong>All Content Ratings</strong> to show every rating again.</p><h2 id="troubleshooting-catalogs" tabindex="-1">Troubleshooting catalogs <a class="header-anchor" href="#troubleshooting-catalogs" aria-label="Permalink to “Troubleshooting catalogs”">​</a></h2><p>If the website cannot load catalog metadata, installation actions are disabled. Choose <strong>Try Again</strong> to reload it. If the problem persists, check your connection or report the error through <a href="/extensions/support">Support</a>.</p>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};